    cs=[c for i,r in enumerate(inp) for c,v in enumerate(r) if v==blk]
    r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
    ms=[]
    for i,r in enumerate(inp):
        for c,v in enumerate(r):
            if v!=0 and v!=blk: ms.append((i,c))
    ex=set(c for i,c in ms if c0<=c<=c1)          # marker columns within block width -> no stripe
    top_pat = [(k-c0) for k in range(c0,c1+1) if k not in ex]  # shifted columns in top rows without inside-markers
    # wait top needs different logic: rows WITH an inside-marker keep shifted block only; rows without -> full row
    out=[[0]*W for _ in range(H)]
    for i in range(r0,r1+1):
        if any(ii==i for ii,_ in ms if c0<=ii<=r1 and c0<=_<=c1):
            # row has inside marker: shifted block + marker
            for k in top_pat: out[i][k]=blk
            for (ii,c) in ms:
                if ii==i: out[i][c]=inp[i][c]
        else:
            for k in range(W): out[i][k]=blk
            for (ii,c) in ms:
                if ii==i: out[i][c]=inp[i][c]
    # bottom: vertical stripes at non-excluded columns from c0..c1
    for i in range(r1+1,H):
        for c in range(c0,c1+1):
            if c not in ex: out[i][c]=blk
        for (ii,c) in ms:
            if ii==i: out[i][c]=inp[i][c]
    return out

