    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\r','\n'); G={}
    for m in re.finditer(r'\((\d+)x(\d+)\)',t):
        h,w=int(m.group(1)),int(m.group(2))
        # key: the word(s) just before the '('
        k=t[max(0,m.start()-40):m.start()].strip().split()[-1]
        rows=[]; s=m.end()
        while len(rows)<h and s<t:
            row=t[s:s+max(w-6,2)].replace(' ','')
            if not row or row[0] not in ('0',str(w)): break
            rows.append([int(x) for x in row.split()])
            s+=len(row)+1
        if all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))
for k,v in G.items(): print(k,len(v),len(v[0]))

